  ('a8124b52-0d60-5105-91a7-b5b5a609bdb3', null, (select id from public.skills where slug = 'write-g7-argument-writing'), null, 'easy',
   $q$Which choice best combines sentences (9) and (10) to show how the ideas are related?$q$, $q$[{"text":"Although Mr. Okafor already owns twelve discs from a summer camp he ran, the school would not need to buy much new equipment.","is_correct":false,"misconception_token":"contrast-for-cause"},{"text":"Mr. Okafor already owns twelve discs from a summer camp he ran, but the school would not need to buy much new equipment.","is_correct":false,"misconception_token":"contrast-for-cause"},{"text":"Because Mr. Okafor already owns twelve discs from a summer camp he ran, the school would not need to buy much new equipment.","is_correct":true},{"text":"Mr. Okafor already owns twelve discs from a summer camp he ran, or the school would not need to buy much new equipment.","is_correct":false,"misconception_token":"wrong-conjunction"}]$q$::jsonb, $q$Because Mr. Okafor already owns twelve discs from a summer camp he ran, the school would not need to buy much new equipment.$q$, $q$The discs Mr. Okafor owns are the reason the school would not need much equipment, so "Because" shows cause and effect. "But" and "Although" signal a contrast that is not there.$q$, 'draft', 'f792b05e-1f42-5786-bf89-4ef0adb08d11')
