insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('abfeb509-6855-58a7-b951-aa4c79fa3520', 'wg7-narrative-writing-p07', (select id from public.skills where slug = 'write-g7-narrative-writing'), null,
        '6-8', $q$The Monkey Who Fell$q$, $q$(1) My little sister Amina loves jungle animals, so I decided to code a game for her eighth birthday. (2) In the game, a monkey jumps from vine to vine to collect bananas. (3) I worked on it every evening for two weeks after finishing my homework. (4) The night before her birthday, I pressed the start button for one final test. (5) The monkey jumped onto the first vine and fell straight through it. (6) My stomach dropped.

(7) I checked the code for the jump, and it looked fine. (8) I checked the code for the bananas, and that looked fine too. (9) Bananas are a good source of potassium. (10) It was almost ten o'clock, and Mom called upstairs that it was time for bed. (11) I noticed that the edges of the vine were a lighter green than the color the monkey was supposed to touch. (12) I recolored the vine, held my breath, and clicked start. (13) The monkey landed, swung, and grabbed a banana.

(14) The game worked.$q$, 'draft')
